<?php require_once __DIR__.'/../lib/app.php';$pageTitle='알림 발송로그';include '_top.php';$pdo=db();$ok=$_GET['ok']??'';$where='1=1';$args=[];if($ok==='1'){$where.=' AND is_success=1';}elseif($ok==='0'){$where.=' AND is_success=0';}$s=$pdo->prepare("SELECT * FROM notification_logs WHERE $where ORDER BY id DESC LIMIT 300");$s->execute($args);$rows=$s->fetchAll();?><div class="section-head"><div><h1>알림 발송로그</h1><p class="muted">API 접수 성공 여부와 응답 전문을 확인합니다.</p></div><div class="actions"><a class="btn sm ghost" href="?">전체</a><a class="btn sm ghost" href="?ok=1">성공</a><a class="btn sm ghost" href="?ok=0">실패</a></div></div><div class="card table-scroll"><table class="table"><tr><th>발송시각</th><th>업무</th><th>수신번호</th><th>템플릿</th><th>결과</th><th>메시지/응답</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['created_at'])?></td><td><?=h($r['event_code'])?></td><td><?=h($r['phone'])?></td><td><?=h($r['template_code'])?></td><td><span class="badge <?=$r['is_success']?'ok-badge':'off-badge'?>"><?=$r['is_success']?'성공':'실패'?></span><div><?=h($r['result_code'])?></div></td><td><details><summary><?=h(mb_strimwidth($r['message_text']?:$r['response'],0,50,'…'))?></summary><pre class="log-pre"><?=h(($r['message_text']?"[메시지]\n{$r['message_text']}\n\n":'')."[응답]\n{$r['response']}")?></pre></details></td></tr><?php endforeach?></table></div><?php include '_bottom.php';?>
